-- ============================================================================
-- H. ACCESS FUNCTIONS (reference implementation of the union / restricted-node rule; ASSUMED semantics)
-- ============================================================================
-- Rule: walk the container ancestors (self included). Find the DEEPEST restricted one; only grants at or below it count
-- (its own grants included). Effective capabilities = union of the roles of all counted grants, where a grant matches
-- when it names the user or one of the user's groups. Active members (not guests) also get workspaces.default_member_role_id
-- implicitly when NO restricted node is on the path. Owner/admin get every capability (bypass). Guests only via grants.
CREATE FUNCTION container_user_caps(p_ws uuid, p_user uuid, p_container uuid)
RETURNS SETOF text LANGUAGE sql STABLE AS $$
  WITH m AS (
    SELECT role_kind FROM workspace_members
    WHERE workspace_id = p_ws AND user_id = p_user AND status = 'active' AND deleted_at IS NULL
  ),
  chain AS (
    SELECT a.id, a.ord, k.is_restricted
    FROM containers c
    CROSS JOIN LATERAL unnest(c.ancestor_ids) WITH ORDINALITY AS a(id, ord)
    JOIN containers k ON k.id = a.id
    WHERE c.id = p_container AND c.workspace_id = p_ws
  ),
  cut AS (SELECT COALESCE(max(ord) FILTER (WHERE is_restricted), 0) AS ord FROM chain),
  roles_found AS (
    SELECT g.role_id
    FROM container_grants g
    JOIN chain ch ON ch.id = g.container_id
    CROSS JOIN cut
    WHERE g.workspace_id = p_ws
      AND ch.ord >= cut.ord
      AND ( g.user_id = p_user
            OR g.group_id IN (SELECT gm.group_id FROM user_group_members gm
                              WHERE gm.workspace_id = p_ws AND gm.user_id = p_user) )
    UNION
    SELECT w.default_member_role_id
    FROM workspaces w
    CROSS JOIN cut
    JOIN m ON m.role_kind = 'member'
    WHERE w.id = p_ws AND cut.ord = 0 AND w.default_member_role_id IS NOT NULL
  )
  SELECT rc.capability FROM role_capabilities rc JOIN roles_found rf ON rf.role_id = rc.role_id
  UNION
  SELECT cp.key FROM capabilities cp WHERE EXISTS (SELECT 1 FROM m WHERE role_kind IN ('owner','admin'))
$$;

-- from core-schema.sql; now: access service, permission engine (plan/tech/04-permissions-spec.md)
-- A task is reachable through ANY list it lives in, plus direct task shares. ASSUMED
CREATE FUNCTION task_user_caps(p_ws uuid, p_user uuid, p_task uuid)
RETURNS SETOF text LANGUAGE sql STABLE AS $$
  SELECT cap FROM task_list_memberships tlm
    CROSS JOIN LATERAL container_user_caps(p_ws, p_user, tlm.list_id) AS cap
    WHERE tlm.workspace_id = p_ws AND tlm.task_id = p_task
  UNION
  SELECT rc.capability FROM task_shares s
    JOIN role_capabilities rc ON rc.role_id = s.role_id
    WHERE s.workspace_id = p_ws AND s.task_id = p_task
      AND ( s.user_id = p_user
            OR s.group_id IN (SELECT gm.group_id FROM user_group_members gm
                              WHERE gm.workspace_id = p_ws AND gm.user_id = p_user) )
$$;

-- from enterprise-delta.sql; now: dropped: cost is a tenant formula field
-- =============================================================================
-- 5. COSTING RULE (ASSUMED, ours). Hourly cost of one person on one day, from the source the tenant chose.
-- Cost of an entry = duration hours x this rate on the entry date. Project cost = sum over its tasks' entries, split by user and billable flag.
-- ClickUp itself has no per-person rate. Its known workaround is a task Formula field = rate field x time tracked (one rate per task),
-- so migrated numbers may differ from ours when several people with different rates share a task. Verify with the client's real data.
-- =============================================================================
CREATE OR REPLACE FUNCTION hourly_cost_cents(p_ws uuid, p_user uuid, p_day date, p_container uuid DEFAULT NULL)
RETURNS TABLE (rate_cents bigint, currency char(3)) LANGUAGE plpgsql STABLE AS $$
DECLARE src text; fid uuid;
BEGIN
  SELECT cs.rate_source, cs.cost_people_field_id INTO src, fid FROM cost_settings cs WHERE cs.workspace_id = p_ws;
  IF src = 'people_field' THEN
    RETURN QUERY SELECT v.money_cents, v.money_currency FROM people_field_values v
      WHERE v.workspace_id = p_ws AND v.user_id = p_user AND v.field_id = fid AND v.money_cents IS NOT NULL;
    RETURN;
  END IF;
  RETURN QUERY SELECT r.rate_cents, r.currency FROM cost_rates r
    WHERE r.workspace_id = p_ws AND r.effective_from <= p_day
      AND (r.user_id = p_user OR (r.user_id IS NULL AND r.container_id IS NOT DISTINCT FROM p_container))
    ORDER BY (r.user_id IS NOT NULL) DESC, (r.container_id IS NOT NULL) DESC, r.effective_from DESC LIMIT 1;
END $$;
